import { Box, Stack, Typography } from '@mui/material'
import type { PendingActionSubmission } from '../state/action_conversation_store'

interface ActionPendingSubmissionRowProps {
    submission: PendingActionSubmission
}

/** Shows submitted text until its backend queue or sent message takes over. */
export function ActionPendingSubmissionRow({ submission }: ActionPendingSubmissionRowProps) {
    const label = submission.state === 'transmitting' ? 'In transmission' : 'Queued'

    return (
        <Box
            aria-label="Pending prompt"
            sx={{
                alignSelf: 'flex-end', bgcolor: 'background.paper', border: 1, borderColor: 'divider',
                borderRadius: 1, flexShrink: 0, maxWidth: '88%', minWidth: 0, overflowWrap: 'anywhere',
                px: 1.25, py: 1,
            }}
        >
            <Stack spacing={0.5}>
                <Typography color="text.secondary" variant="caption">{label}</Typography>
                <Typography variant="body2">{submission.content}</Typography>
            </Stack>
        </Box>
    )
}

import { useSyncExternalStore } from 'react'
import type { ActionConversationChatlogTracker } from './action_conversation_chatlog_tracker'
import { ActionPendingSubmissionRow } from './action_pending_submission_row'

interface ActionConversationPendingSubmissionsProps {
    tracker: ActionConversationChatlogTracker
}

/** Subscribes only pending rows to submission changes. */
export function ActionConversationPendingSubmissions({ tracker }: ActionConversationPendingSubmissionsProps) {
    const submissions = useSyncExternalStore(
        tracker.subscribeSubmissions,
        tracker.getSubmissions,
        tracker.getSubmissions,
    )

    return submissions.map((submission) => <ActionPendingSubmissionRow key={submission.id} submission={submission} />)
}

